/* Modo historia · Temporada 1 · Arco Capital Federal — Episodio 01: «Los inicios»
   Cada jefe tiene 15 misiones en tres actos: I «Mandadero» (1–5, cortas, para aprender), II «De confianza» (6–10, de horas)
   y III «Mano derecha» (11–15, largas; la 15 es el final del capítulo y dura casi un día). Las cuatro historias se pueden jugar;
   el final (la 15) solo con la pandilla de la que sos. Cada misión hecha destraba su bloque de diario en la Crónica (lore).
   Por debajo corre un hilo que nadie nombra: la Fundación La Esquina, y una señora que sirve cafés y quiere ser intendenta. */
import type { Gang, Mission, MissionStep, StatKey } from "./types.js";

export const EPISODE = { season: 1, arc: "Arco Capital Federal", num: "01", name: "Los inicios" };
export const STORY_NAME: Record<Gang, string> = { familia: "La herencia", sindicato: "Primera plana", barra: "El clásico", amarillos: "Bajada de bandera" };
export const ACT_NAMES = ["Mandadero", "De confianza", "Mano derecha"];

type Chk = [StatKey, string, string, string];                       // atributo, qué hacés, si sale bien, si sale mal
type Pel = ["pelea", string, string, number, string, string];      // qué pasa, contra quién, cuán duro, si ganás, si perdés
interface H { t: string; place: string; intro: string; steps: (Chk | Pel)[]; back: string; outro: string; lore: string }

/* el ritmo de cada número de misión (1 a 15) */
const MINS   = [5, 8, 12, 15, 20,  60, 90, 120, 180, 240,  240, 300, 360, 480, 1080]; // en el lugar (sin contar el viaje)
const ENERGY = [5, 6, 6, 7, 8,     10, 10, 11, 12, 12,     14, 14, 15, 16, 20];
const DIFF   = [5, 5, 6, 6, 7,     8, 9, 9, 10, 11,        13, 14, 15, 16, 17];
const GOLD   = [40, 50, 60, 70, 90,  200, 240, 280, 320, 360,  600, 700, 800, 900, 4000];
const XP     = [25, 30, 35, 40, 50,      90, 100, 110, 120, 140,   200, 220, 240, 260, 800];
const RESP   = [4, 5, 6, 7, 8,          12, 14, 16, 18, 20,       30, 32, 35, 40, 250];
const HEAT   = [5, 6, 7, 8, 10,          12, 14, 15, 16, 18,       20, 22, 24, 26, 35];
const AFF    = [10, 6, 6, 6, 8,           10, 10, 10, 10, 12,       15, 15, 15, 15, 30];

function story(g: Gang, list: H[]): Mission[] {
  return list.map((h, i) => {
    const act = i < 5 ? 0 : i < 10 ? 1 : 2;
    const work = h.steps.length, per = (ENERGY[i] - 1) / work;
    const steps: MissionStep[] = h.steps.map(st => st[0] === "pelea"
      ? { text: st[1], fight: { name: st[2], mult: st[3] }, energy: per, win: st[4], lose: st[5] }
      : { text: st[1], stat: st[0], diff: DIFF[i], energy: per, dmg: act ? 0.12 : 0.08, ok: st[2], ko: st[3] });
    steps.push({ text: h.back, energy: 1, auto: true, ok: h.outro });
    /* lo que pide: los dos atributos que más usa */
    const count: Partial<Record<StatKey, number>> = {};
    for (const st of h.steps) if (st[0] !== "pelea") count[st[0]] = (count[st[0]] ?? 0) + 1;
    const top = (Object.keys(count) as StatKey[]).sort((a, b) => count[b]! - count[a]!).slice(0, 2);
    return {
      id: `h-${g}-${i + 1}`, gang: g, tier: act, rank: [0, 2, 3][act], place: h.place, mins: MINS[i],
      title: h.t, intro: h.intro, steps, outro: h.outro, lore: h.lore, story: i + 1, final: i === 14 || undefined,
      req: Object.fromEntries(top.map((k, j) => [k, DIFF[i] + 2 - j])),
      aff: AFF[i], reward: { gold: GOLD[i], xp: XP[i], resp: RESP[i], heat: HEAT[i] }
    } as Mission;
  });
}

